        raise exception 'card cannot be moved to an archived board';
      end if;
      if not public.is_board_editor(new.board_id) then
        raise exception 'card can only be moved to a board where the user is an editor';
      end if;
    else
      raise exception 'card cannot be modified';
    end if;
  end if;
  return new;
end;
$$;

