alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend(p_user_id uuid, p_friend_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.friendships f
    where ((f.requester_id = p_user_id and f.addressee_id = p_friend_id)
          or (f.requester_id = p_friend_id and f.addressee_id = p_user_id))
      and f.status = 'accepted'
  );
$$;

create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'friendship updates require authentication';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending' then
      raise exception 'new friendships must be pending';
    end if;
    if new.requester_id = new.addressee_id then
      raise exception 'a user cannot friend themselves';
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if old.requester_id <> new.requester_id and old.addressee_id <> new.addressee_id then
      raise exception 'friendship endpoints cannot be changed';
    end if;
    if old.status = 'accepted' then
      raise exception 'accepted friendships cannot be modified';
    end if;
    if new.status <> 'accepted' then
      raise exception 'only pending requests can be accepted';
    end if;
    if new.requester_id = auth.uid() then
      raise exception 'requesters cannot accept their own requests';
    end if;
    if new.addressee_id <> auth.uid() then
      raise exception 'only the addressee can accept a request';
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    if old.requester_id <> auth.uid() and old.addressee_id <> auth.uid() then
      raise exception 'only participants can delete a friendship';
    end if;
    return old;
  else
    raise exception 'unknown trigger operation: %', tg_op;
  end if;
end;
$$;

create trigger friendships_enforce_update
before insert or update or delete on public.friendships
for each row execute function public.enforce_friendship_update();

create policy "friendships_select_participants"
on public.friendships for select to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "friendships_insert_requester"
on public.friendships for insert to authenticated
with check (requester_id = auth.uid() and status = 'pending');

create policy "friendships_update_addressee_accept"
on public.friendships for update to authenticated
using (status = 'pending' and addressee_id = auth.uid() and requester_id <> auth.uid())
with check (status = 'accepted');

create policy "friendships_delete_participant"
on public.friendships for delete to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "posts_select_audience"
on public.posts for select to anon, authenticated
using (
  audience = 'public'
  or author_id = auth.uid()
  or public.is_friend(auth.uid(), author_id)
);

create policy "posts_insert_own"
on public.posts for insert to authenticated
with check (author_id = auth.uid());

create policy "posts_update_own"
on public.posts for update to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "posts_delete_own"
on public.posts for delete to authenticated
using (author_id = auth.uid());
```

