        if old.status = 'pending' and public.auth.uid() <> old.addressee_id then
          raise exception 'only the addressee can accept a friend request';
        end if;
        if public.auth.uid() is distinct from old.requester_id and public.auth.uid() is distinct from old.addressee_id then
          raise exception 'only participants of a friendship can modify it';
        end if;
      end if;
    end if;
  end if;
  return new;
end;
