create or replace function public.enforce_friendship_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'friendships insert requires authenticated user';
  end if;
  if new.requester_id <> auth.uid() then
    raise exception 'you can only send friend requests where you are the requester';
