as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is distinct from new.created_by then
      raise exception 'request created_by must match authenticated user';
    end if;
    if new.status <> 'open' then
      raise exception 'new requests must have status open';
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if old.id <> new.id then raise exception 'request id immutable'; end if;
    if old.unit_id <> new.unit_id then raise exception 'request unit_id immutable'; end if;
