create or replace function public.mask_email(p_email text)
returns text
language sql
immutable
as $$
  select case when p_email is null then null
              when position('@' in p_email) = 0 then '***'
              else substring(p_email, 1, 1) || '***' || substring(p_email from position('@' in p_email)) end;
$$;

create or replace function public.mask_phone(p_phone text)
returns text
language sql
immutable
as $$
  select case when p_phone is null then '******'
              when length(p_phone) <= 4 then '******' || p_phone
              else '******' || substring(p_phone from length(p_phone) - 3) end;
$$;

