create or replace function public.class_spot_enforced_update()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'UPDATE' then
    if tg_arg_name_matches then
      if tg_arg_names[] not array['status'] then
        raise exception 'only status may be updated on class_spots';
      end if;
    else
      if old.class_id <> new.class_id or old.user_id <> new.user_id then
        raise exception 'class_spot class_id and user_id cannot be changed';
      end if;
    end if;

    perform pg_advisory_xact_lock(hashtext('class_spots_' || new.class_id::text)::bigint);

    if new.status = 'enrolled' then
      perform 1 from public.class_spots s where s.class_id = new.class_id and s.user_id <> new.user_id and s.status = 'enrolled';
      if not found then
        raise exception 'cannot enroll: not waitlisted or no room';
      end if;
      perform 1 from public.classes c where c.id = new.class_id;
      if not found then
        raise exception 'unknown class';
      end if;
      if (select count(*)::integer from public.class_spots s where s.class_id = new.class_id and s.status = 'enrolled') >= c.capacity then
        raise exception 'class is full';
      end if;
    elsif new.status = 'waitlisted' then
      if old.status <> 'waitlisted' then
        raise exception 'can only move from waitlisted to waitlisted';
      end if;
    else
      raise exception 'invalid status';
    end if;

    return new;
  elsif tg_op = 'DELETE' then
    return old;
  else
    raise exception 'unknown trigger op';
  end if;
end;
$$;

