create or replace function public.class_has_capacity(p_class_id bigint, p_enrolled_count_out integer default null)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select c.capacity - (select count(*)::integer from public.class_spots s where s.class_id = c.id and s.status = 'enrolled') from public.classes c where c.id = p_class_id),
    p_enrolled_count_out
  );
$$;

create or replace function public.class_spot_enforce_immutable_columns()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'UPDATE' then
    if tg_arg_name_exists('class_id') and tg_arg_name_exists('user_id') then
      if new.class_id <> old.class_id or new.user_id <> old.user_id then
        raise exception 'class_id and user_id of a class spot are immutable';
      end if;
    end if;
    if new.status <> old.status then
      if auth.uid() is null then
        raise exception 'class spot status change is not allowed';
      end if;
      if old.status = 'enrolled' then
        raise exception 'enrolled spots cannot be downgraded';
      end if;
      if auth.uid() <> old.user_id then
        raise exception 'only the owner of a waitlisted spot can promote it to enrolled';
      end if;
      if old.status = 'waitlisted' and new.status = 'enrolled' then
        perform 1 from public.class_spots s where s.class_id = new.class_id and s.status = 'enrolled' and s.user_id <> new.user_id having count(*) >= (select c.capacity from public.classes c where c.id = new.class_id);
        if not found then
          raise exception 'no capacity to promote this waitlisted spot to enrolled';
        end if;
      elsif old.status <> 'waitlisted' or new.status <> 'enrolled' then
        raise exception 'invalid class spot status transition';
      end if;
    end if;
  end if;
  return new;
end;
$$;

